#!/usr/bin/env bun
/**
 * Configure Technitium DNS Server via its HTTP API.
 *
 * Idempotent: creates primary zones, DNS records, forwarder zones,
 * blocklists, and forwarders from JSON files generated by the NixOS config.
 *
 * Required environment:
 *   TECHNITIUM_URL                    (default http://127.0.0.1:5380)
 *   TECHNITIUM_TOKEN_FILE             API token (preferred auth)
 *   TECHNITIUM_ADMIN_PASS_FILE        admin password (fallback auth)
 *   TECHNITIUM_ADMIN_USER             (default "admin")
 *   TECHNITIUM_ZONE_RECORDS_FILE      JSON list of DNS records
 *   TECHNITIUM_FORWARDER_ZONES_FILE   JSON list of forwarder zones
 *   TECHNITIUM_BLOCKLISTS_FILE        JSON list of blocklist URLs
 *   TECHNITIUM_FORWARDERS_FILE        JSON list of forwarder addresses
 */

const url = process.env.TECHNITIUM_URL ?? "http://127.0.0.1:5380";
const tokenFile = process.env.TECHNITIUM_TOKEN_FILE ?? "";
const adminUser = process.env.TECHNITIUM_ADMIN_USER ?? "admin";
const adminPassFile = process.env.TECHNITIUM_ADMIN_PASS_FILE ?? "";

async function readFile(path: string): Promise<string> {
  if (path) {
    try {
      return (await Bun.file(path).text()).trim();
    } catch (e) {
      console.error(`Warning: could not read ${path}: ${e}`);
    }
  }
  return "";
}

const token = await readFile(tokenFile);
const adminPass = (await readFile(adminPassFile)) || "admin";

// ---------------------------------------------------------------------------
// Low-level HTTP helpers
// ---------------------------------------------------------------------------

/** Make an API request. Returns parsed JSON or null on failure. */
async function request(
  ep: string,
  data?: Record<string, string>,
  method = "GET",
  authToken?: string,
): Promise<any> {
  const headers: Record<string, string> = {};
  if (authToken) headers["Authorization"] = "Bearer " + authToken;
  const init: RequestInit = {
    headers,
    signal: AbortSignal.timeout(30_000),
  };
  if (data) {
    headers["Content-Type"] = "application/x-www-form-urlencoded";
    init.method = method;
    init.body = new URLSearchParams(data).toString();
  } else {
    init.method = method;
  }
  try {
    const res = await fetch(url + ep, init);
    if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    return await res.json();
  } catch (e) {
    console.error(`  HTTP error on ${ep}: ${e}`);
    return null;
  }
}

/** True if response is an object with status == 'ok'. */
function isOk(resp: unknown): boolean {
  return (
    typeof resp === "object" &&
    resp !== null &&
    (resp as Record<string, unknown>).status === "ok"
  );
}

/** True if response indicates an auth failure. */
function isInvalidToken(resp: unknown): boolean {
  return (
    typeof resp === "object" &&
    resp !== null &&
    (resp as Record<string, unknown>).status === "invalid-token"
  );
}

// ---------------------------------------------------------------------------
// Auth: try existing token → admin login → fail
// ---------------------------------------------------------------------------

async function getAuthToken(): Promise<string | null> {
  // 1. Try token file content as a Bearer token
  if (token) {
    console.log(`Trying token from ${tokenFile} ...`);
    const resp = await request("/api/stats", undefined, "GET", token);
    if (isOk(resp)) {
      console.log("Token authenticated successfully.");
      return token;
    } else if (isInvalidToken(resp)) {
      console.log("Token rejected (invalid-token).");
    } else {
      console.log(`Token auth failed: ${JSON.stringify(resp)}`);
    }
  }

  // 2. Try admin password from sops secret (or default "admin")
  console.log(`Trying login with ${adminUser}/<password-from-file> ...`);
  const login = await request(
    "/api/user/login",
    { user: adminUser, pass: adminPass },
    "POST",
  );
  if (isOk(login) && (login as any)?.token) {
    console.log("Login successful.");
    return (login as any).token as string;
  } else {
    console.log(`Login failed: ${JSON.stringify(login)}`);
  }

  console.error("FATAL: Could not authenticate with Technitium API.");
  console.error(
    "  - Put the admin password in the sops secret 'technitium_admin_password'.",
  );
  console.error(
    "  - Or generate an API token via the web UI and save it to the sops secret 'technitium_api_key'.",
  );
  return null;
}

// ---------------------------------------------------------------------------
// Wait for API to be reachable (unauthenticated health check)
// ---------------------------------------------------------------------------

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Poll /api/stats without auth until it responds (any response = up). */
async function waitForApi(maxWait = 120): Promise<boolean> {
  for (let i = 0; i < maxWait; i++) {
    try {
      await fetch(url + "/api/stats", {
        signal: AbortSignal.timeout(5_000),
      });
      // We got any HTTP response — API is up. We don't care about
      // the body here; auth is handled separately.
      return true;
    } catch {
      // not up yet
    }
    await sleep(1000);
  }
  return false;
}

// ---------------------------------------------------------------------------
// Configuration helpers
// ---------------------------------------------------------------------------

async function getZoneType(
  t: string,
  zoneName: string,
): Promise<string | null> {
  const r = await request(
    `/api/zones/options?zone=${encodeURIComponent(zoneName)}`,
    undefined,
    "GET",
    t,
  );
  if (isOk(r) && typeof r === "object" && r !== null) {
    return (r as Record<string, any>).type ?? null;
  }
  return null;
}

interface ZoneRecord {
  zone?: string;
  name?: string;
  type?: string;
  value?: string;
  [key: string]: unknown;
}

async function zone(t: string): Promise<void> {
  const zoneFile = process.env.TECHNITIUM_ZONE_RECORDS_FILE ?? "";
  if (!zoneFile) {
    console.error("WARNING: no zone records file found, skipping.");
    return;
  }
  let records: ZoneRecord[];
  try {
    records = (await Bun.file(zoneFile).json()) as ZoneRecord[];
  } catch {
    console.error("WARNING: no zone records file found, skipping.");
    return;
  }

  // Group records by zone and create each primary zone
  const zonesCreated = new Set<string>();
  for (const rec of records) {
    const zoneName = rec.zone ?? "diekvoss.net";
    if (!zonesCreated.has(zoneName)) {
      console.log(`Creating zone ${zoneName} ...`);
      const r = await request(
        "/api/zones/create",
        { zone: zoneName, type: "Primary" },
        "POST",
        t,
      );
      if (isOk(r)) {
        console.log(`  Zone created.`);
      } else if (
        typeof r === "object" &&
        r !== null &&
        String((r as Record<string, any>).errorMessage ?? "")
          .toLowerCase()
          .includes("already exists")
      ) {
        console.log(`  Zone already exists, continuing.`);
      } else {
        console.log(`  Warning: zone create failed: ${JSON.stringify(r)}`);
      }
      zonesCreated.add(zoneName);
    }
  }

  for (const rec of records) {
    const name = rec.name ?? "@";
    const zoneName = rec.zone ?? "diekvoss.net";
    const domain = name === "@" ? zoneName : `${name}.${zoneName}`;
    const payload: Record<string, string> = {};
    for (const [k, v] of Object.entries(rec)) {
      if (v !== undefined && v !== null) payload[k] = String(v);
    }
    payload["domain"] = domain;
    console.log(
      `  Adding record: ${domain} ${rec.type ?? "A"} ${rec.value ?? ""} ...`,
    );
    const r = await request("/api/zones/records/add", payload, "POST", t);
    if (!isOk(r)) {
      const msg =
        typeof r === "object" && r !== null
          ? String((r as Record<string, any>).errorMessage ?? "")
          : "";
      if (
        msg.toLowerCase().includes("already exists") ||
        msg.toLowerCase().includes("duplicate")
      ) {
        console.log(`    Already exists, skipped.`);
      } else {
        console.log(`    ERROR: ${JSON.stringify(r)}`);
      }
    }
  }
}

interface ForwarderZone {
  zone?: string;
  protocol?: string;
  forwarder?: string;
}

async function forwarderZones(t: string): Promise<void> {
  const fwFile = process.env.TECHNITIUM_FORWARDER_ZONES_FILE ?? "";
  if (!fwFile) {
    console.error("WARNING: no forwarder zones file found, skipping.");
    return;
  }
  let zones: ForwarderZone[];
  try {
    zones = (await Bun.file(fwFile).json()) as ForwarderZone[];
  } catch {
    console.error("WARNING: no forwarder zones file found, skipping.");
    return;
  }

  for (const zoneCfg of zones) {
    const zoneName = zoneCfg.zone ?? "";
    const protocol = zoneCfg.protocol ?? "Udp";
    const forwarder = zoneCfg.forwarder ?? "";
    console.log(`Creating forwarder zone ${zoneName} ...`);
    const r = await request(
      "/api/zones/create",
      { zone: zoneName, type: "Forwarder", protocol, forwarder },
      "POST",
      t,
    );
    if (isOk(r)) {
      console.log(`  Forwarder zone created.`);
    } else if (
      typeof r === "object" &&
      r !== null &&
      String((r as Record<string, any>).errorMessage ?? "")
        .toLowerCase()
        .includes("already exists")
    ) {
      // Check if it's already a forwarder zone
      const existingType = await getZoneType(t, zoneName);
      if (existingType === "Forwarder") {
        console.log(`  Forwarder zone already exists, continuing.`);
      } else {
        console.log(
          `  Zone exists as ${existingType}, deleting to recreate as Forwarder...`,
        );
        const delR = await request(
          "/api/zones/delete",
          { zone: zoneName },
          "POST",
          t,
        );
        if (isOk(delR)) {
          const r2 = await request(
            "/api/zones/create",
            { zone: zoneName, type: "Forwarder", protocol, forwarder },
            "POST",
            t,
          );
          if (isOk(r2)) {
            console.log(`  Forwarder zone created after delete.`);
          } else {
            console.log(
              `  Warning: forwarder zone recreate failed: ${JSON.stringify(r2)}`,
            );
          }
        } else {
          console.log(
            `  Warning: could not delete existing zone: ${JSON.stringify(delR)}`,
          );
        }
      }
    } else {
      console.log(
        `  Warning: forwarder zone create failed: ${JSON.stringify(r)}`,
      );
    }
  }
}

async function blocklists(t: string): Promise<void> {
  const blFile = process.env.TECHNITIUM_BLOCKLISTS_FILE ?? "";
  if (!blFile) {
    console.error("WARNING: no blocklists file found, skipping.");
    return;
  }
  let urls: string[];
  try {
    urls = (await Bun.file(blFile).json()) as string[];
  } catch {
    console.error("WARNING: no blocklists file found, skipping.");
    return;
  }
  if (!urls || urls.length === 0) return;
  console.log("Configuring blocklists ...");
  // Technitium /api/settings/set with blockListUrls overwrites on each call,
  // so send all URLs at once joined by commas.
  const combined = urls.join(",");
  const r = await request(
    "/api/settings/set",
    { blockListUrls: combined },
    "POST",
    t,
  );
  if (isOk(r)) {
    console.log(`  OK: set ${urls.length} blocklist URLs`);
  } else {
    console.error(`  WARNING: could not set blocklists: ${JSON.stringify(r)}`);
    // Fallback: try one at a time via add endpoints
    const endpoints = ["/api/blockList/urls/add", "/api/blockList/urls/set"];
    for (const blockUrl of urls) {
      console.log(`  Adding blocklist: ${blockUrl}`);
      let added = false;
      for (const ep of endpoints) {
        const r = await request(ep, { url: blockUrl }, "POST", t);
        if (isOk(r)) {
          console.log(`    OK via ${ep}`);
          added = true;
          break;
        } else if (
          typeof r === "object" &&
          r !== null &&
          (r as Record<string, any>).status === "error"
        ) {
          const msg = String((r as Record<string, any>).errorMessage ?? "");
          if (
            msg.toLowerCase().includes("already exists") ||
            msg.toLowerCase().includes("duplicate")
          ) {
            console.log(`    Already exists, skipped.`);
            added = true;
            break;
          }
        }
      }
      if (!added) {
        console.error(`    WARNING: could not add blocklist`);
      }
    }
  }
}

async function forwarders(t: string): Promise<void> {
  const fwFile = process.env.TECHNITIUM_FORWARDERS_FILE ?? "";
  if (!fwFile) {
    console.error("WARNING: no forwarders file found, skipping.");
    return;
  }
  let fwds: string[];
  try {
    fwds = (await Bun.file(fwFile).json()) as string[];
  } catch {
    console.error("WARNING: no forwarders file found, skipping.");
    return;
  }
  if (!fwds || fwds.length === 0) return;
  console.log("Configuring forwarders ...");
  // Technitium /api/settings/set with forwarders overwrites on each call,
  // so send all forwarders at once joined by commas.
  const combined = fwds.join(",");
  const r = await request(
    "/api/settings/set",
    {
      forwarders: combined,
      forwarderProtocol: "Quic",
      concurrentForwarding: "true",
      forwarderRetries: "3",
      forwarderTimeout: "2000",
      forwarderConcurrency: "2",
    },
    "POST",
    t,
  );
  if (isOk(r)) {
    console.log(`  OK: set ${fwds.length} forwarders`);
  } else {
    console.error(`  WARNING: could not set forwarders: ${JSON.stringify(r)}`);
    // Fallback: try one at a time via add endpoints
    const endpoints = ["/api/forwarders/add", "/api/forwarders/set"];
    for (const fwd of fwds) {
      console.log(`  Adding forwarder: ${fwd}`);
      let added = false;
      for (const ep of endpoints) {
        const r = await request(ep, { address: fwd }, "POST", t);
        if (isOk(r)) {
          console.log(`    OK via ${ep}`);
          added = true;
          break;
        } else if (
          typeof r === "object" &&
          r !== null &&
          (r as Record<string, any>).status === "error"
        ) {
          const msg = String((r as Record<string, any>).errorMessage ?? "");
          if (
            msg.toLowerCase().includes("already exists") ||
            msg.toLowerCase().includes("duplicate")
          ) {
            console.log(`    Already exists, skipped.`);
            added = true;
            break;
          }
        }
      }
      if (!added) {
        console.error(`    WARNING: could not add forwarder`);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  console.log(`Waiting for Technitium API at ${url} ...`);
  if (!(await waitForApi())) {
    console.error(
      "FATAL: Technitium API did not become reachable within 120 seconds.",
    );
    process.exit(1);
  }
  console.log("API is reachable.");

  const t = await getAuthToken();
  if (!t) {
    process.exit(1);
  }

  await forwarderZones(t);
  await zone(t);
  await blocklists(t);
  await forwarders(t);

  console.log("Technitium configuration complete.");
}

if (import.meta.main) {
  await main();
}
